import { apiRequestFile } from '@/services/apiClient';
import { exportFile, type FileExportOutcome } from '@/services/fileExport';
import type { ArcadeGroup } from '@/services/arcadeGroups';
import { RESULT_FORMATS, resultFileName, type ResultFormat } from './groupResultsFormat';

/**
 * Downloads the host's result sheet as a CSV or PDF generated by the server,
 * then saves it (web) or opens the share sheet (phone).
 */
export async function downloadGroupResults(
  accessToken: string,
  group: Pick<ArcadeGroup, 'id' | 'title' | 'game' | 'endedAt'>,
  format: ResultFormat,
  shareTitle: string,
): Promise<FileExportOutcome> {
  const file = await apiRequestFile(`/arcade/groups/${group.id}/results.${format}`, accessToken);
  return exportFile({
    bytes: file.bytes,
    fileName: resultFileName(group, format),
    mimeType: RESULT_FORMATS[format].mimeType,
    uti: RESULT_FORMATS[format].uti,
    title: shareTitle,
  });
}
